const input = $input.first().json;
const body = input.body || input;

const errors = [];

// Déclarations AVANT utilisation
const validProviders = ['openai', 'openai-mini', 'claude', 'claude-haiku', 'gemini', 'gemini-pro', 'mistral',
'mistral-premium'];
const defaultModels = {
  openai: 'gpt-4o-search-preview',
  'openai-mini': 'gpt-4o-mini-search-preview',
  claude: 'claude-sonnet-4-20250514',
  'claude-haiku': 'claude-haiku-4-5-20251001',
  gemini: 'gemini-2.5-flash',
  'gemini-pro': 'gemini-2.5-pro',
  mistral: 'mistral-medium-2505',
  'mistral-premium': 'mistral-medium-2505'
};

if (!body.query) {
  errors.push('Missing required parameter: query');
}

const provider = body.provider || 'gemini';

if (!validProviders.includes(provider)) {
  errors.push(`Invalid provider: '${provider}'. Valid options: ${validProviders.join(', ')}`);
}

// Check required API keys based on provider
if (provider.startsWith('openai') && !body.openai_api_key) {
  errors.push('Missing openai_api_key for OpenAI provider');
}
if (provider.startsWith('claude') && !body.anthropic_api_key) {
  errors.push('Missing anthropic_api_key for Claude provider');
}
if (provider.startsWith('gemini') && !body.google_api_key) {
  errors.push('Missing google_api_key for Gemini provider');
}
if (provider.startsWith('mistral') && !body.mistral_api_key) {
  errors.push('Missing mistral_api_key for Mistral provider');
}

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: errors.join(', '),
        status: 'BAD_REQUEST'
      }
    }
  }];
}

const opts = body.options || {};

return [{
  json: {
    valid: true,
    query: body.query,
    provider,
    provider_type: provider.split('-')[0],
    model: body.model || defaultModels[provider],
    user_id: body.user_id,
    openai_api_key: body.openai_api_key,
    anthropic_api_key: body.anthropic_api_key,
    google_api_key: body.google_api_key,
    mistral_api_key: body.mistral_api_key,
    options: {
      search_depth: opts.search_depth || 'medium',
      max_results: opts.max_results || 3,
      language: opts.language || 'fr',
      allowed_domains: opts.allowed_domains || [],
      blocked_domains: opts.blocked_domains || [],
      include_sources: opts.include_sources !== false
    },
    output_schema: body.output_schema || null,
    allowed_context: body.allowed_context || null,
    messages: body.messages || null
  }
}];

