const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const usage = {
  input_tokens: input.usage?.input_tokens || 0,
  output_tokens: input.usage?.output_tokens || 0,
  total_tokens: (input.usage?.input_tokens || 0) + (input.usage?.output_tokens || 0)
};

function getDomain(url) {
  if (!url) return '';
  const match = url.match(/^https?:\/\/([^\/]+)/);
  return match ? match[1] : '';
}

try {
  let textContent = '';
  const sources = [];
  let structuredData = null;

  for (const block of (input.content || [])) {
    // Extraire le texte
    if (block.type === 'text') {
      textContent += block.text;
    }

    // Extraire les sources web (handle both array and error object)
    if (block.type === 'web_search_tool_result') {
      const results = block.content;
      // Check if content is an array (success) or object (error like web_search_tool_result_error)
      if (Array.isArray(results)) {
        for (const result of results) {
          if (result.type === 'web_search_result') {
            sources.push({
              title: result.title || 'Source',
              url: result.url,
              domain: getDomain(result.url)
            });
          }
        }
      }
      // If error object, skip - no sources to extract
    }

    // Extraire les données structurées (tool_use, but not web_search)
    if (block.type === 'tool_use' && block.name !== 'web_search') {
      structuredData = {
        tool_name: block.name,
        data: block.input
      };
    }
  }

  // Native Anthropic content array as llm_response
  const llm_response = input.content || [];

  return [{
    json: {
      normalized: true,
      provider: prevData.provider,
      query: prevData.query,
      content: textContent,
      sources,
      structured_data: structuredData,
      search_performed: sources.length > 0,
      has_structured_output: structuredData !== null,
      usage,
      llm_response
    }
  }];
} catch (e) {
  return [{
    json: {
      normalized: false,
      provider: prevData.provider,
      error: e.message,
      llm_response: []
    }
  }];
}

const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const usage = {
  input_tokens: input.usageMetadata?.promptTokenCount || 0,
  output_tokens: input.usageMetadata?.candidatesTokenCount || 0,
  total_tokens: input.usageMetadata?.totalTokenCount || 0
};

function getDomain(url) {
  if (!url) return '';
  const match = url.match(/^https?:\/\/([^\/]+)/);
  return match ? match[1] : '';
}

try {
  let textContent = '';
  const sources = [];
  let structuredData = null;

  const candidate = input.candidates?.[0];
  const parts = candidate?.content?.parts || [];

  for (const part of parts) {
    // Extraire le texte
    if (part.text) {
      textContent += part.text;
    }

    // Extraire les données structurées (functionCall)
    if (part.functionCall && part.functionCall.name !== 'google_search') {
      structuredData = {
        tool_name: part.functionCall.name,
        data: part.functionCall.args
      };
    }
  }

  // Extraire les sources (grounding metadata)
  const grounding = candidate?.groundingMetadata;
  const chunks = grounding?.groundingChunks || [];

  for (const chunk of chunks) {
    if (chunk.web) {
      sources.push({
        title: chunk.web.title || 'Source',
        url: chunk.web.uri,
        domain: getDomain(chunk.web.uri)
      });
    }
  }

  // Build llm_response in Anthropic format for Gemini
  const llm_response = [{ type: 'text', text: textContent }];

  return [{
    json: {
      normalized: true,
      provider: prevData.provider,
      query: prevData.query,
      content: textContent,
      sources,
      structured_data: structuredData,
      search_performed: sources.length > 0,
      has_structured_output: structuredData !== null,
      usage,
      llm_response
    }
  }];
} catch (e) {
  return [{
    json: {
      normalized: false,
      provider: prevData.provider,
      error: e.message,
      llm_response: []
    }
  }];
}

