const input = $input.first().json;
const prevData = $('Validate Input').first().json;

// Helper to build _trace object with llm_response
const buildTrace = () => ({
  llm_response: input.llm_response || [],
  model: prevData.model,
  tokens: input.usage || null,
  latency_ms: Date.now() - (prevData.startTime || Date.now())
});

try {
  if (!input.normalized) {
    return [{
      json: {
        success: false,
        error: {
          code: 500,
          message: input.error || 'Failed to normalize response',
          status: 'NORMALIZE_ERROR'
        },
        meta: { provider: prevData.provider },
        usage: input.usage || null,
        _trace: {
          llm_response: input.llm_response || [],
          model: prevData.model,
          tokens: input.usage || null,
          latency_ms: Date.now() - (prevData.startTime || Date.now())
        }
      }
    }];
  }

  // Si données structurées (tool_use), les retourner directement
  if (input.structured_data) {
    return [{
      json: {
        success: true,
        data: input.structured_data.data,
        sources: input.sources || [],
        meta: {
          provider: prevData.provider,
          tool_used: input.structured_data.tool_name,
          search_performed: input.search_performed,
          sources_count: (input.sources || []).length
        },
        usage: input.usage || null,
        _trace: buildTrace()
      }
    }];
  }

  // Sinon, retour classique (texte brut)
  return [{
    json: {
      success: true,
      data: {
        query: prevData.query,
        content: input.content,
        sources: input.sources || []
      },
      meta: {
        provider: prevData.provider,
        search_performed: input.search_performed,
        sources_count: (input.sources || []).length
      },
      usage: input.usage || null,
      _trace: buildTrace()
    }
  }];
} catch (e) {
  return [{
    json: {
      success: false,
      error: {
        code: 500,
        message: 'Failed to format output: ' + e.message,
        status: 'FORMAT_ERROR'
      },
      meta: { provider: prevData.provider },
      usage: input.usage || null,
      _trace: {
        llm_response: input.llm_response || [],
        model: prevData.model,
        tokens: input.usage || null,
        latency_ms: Date.now() - (prevData.startTime || Date.now())
      }
    }
  }];
}

