const data = $input.first().json;

// Si pas de contexte à vérifier, passer directement
if (!data.allowed_context) {
  return [{
    json: {
      ...data,
      context_check: {
        required: false,
        valid: true
      }
    }
  }];
}

const ctx = data.allowed_context;

// Construire le prompt de vérification (générique)
const checkPrompt = `Tu es un modérateur de contenu. Vérifie si une requête correspond au contexte autorisé.

CONTEXTE AUTORISÉ:
${ctx.description}

REQUÊTE:
"${data.query}"

RÈGLES:
- Réponds UNIQUEMENT par un JSON valide
- {"valid": true} si la requête est dans le contexte
- {"valid": false, "reason": "explication courte"} si hors contexte
- Sois strict mais juste

JSON:`;

// Construire le body/url/headers selon le provider
let llmBody, apiUrl, headers;

switch (data.provider_type) {
  case 'claude':
    apiUrl = 'https://api.anthropic.com/v1/messages';
    headers = {
      'x-api-key': data.anthropic_api_key,
      'anthropic-version': '2023-06-01',
      'Content-Type': 'application/json'
    };
    llmBody = {
      model: data.model,
      max_tokens: 100,
      messages: [{ role: 'user', content: checkPrompt }]
    };
    break;

  case 'openai':
    apiUrl = 'https://api.openai.com/v1/chat/completions';
    headers = {
      'Authorization': `Bearer ${data.openai_api_key}`,
      'Content-Type': 'application/json'
    };
    llmBody = {
      model: data.model,
      max_tokens: 100,
      messages: [{ role: 'user', content: checkPrompt }]
    };
    break;

  case 'gemini':
    apiUrl = `https://generativelanguage.googleapis.com/v1beta/models/${data.model}:generateContent?key=${data.google_api_key}`;
    headers = { 'Content-Type': 'application/json' };
    llmBody = {
      contents: [{ parts: [{ text: checkPrompt }] }],
      generationConfig: { maxOutputTokens: 100 }
    };
    break;

  case 'mistral':
    apiUrl = 'https://api.mistral.ai/v1/chat/completions';
    headers = {
      'Authorization': `Bearer ${data.mistral_api_key}`,
      'Content-Type': 'application/json'
    };
    llmBody = {
      model: data.model,
      max_tokens: 100,
      messages: [{ role: 'user', content: checkPrompt }]
    };
    break;

  default:
    // Provider non supporté pour context check - skip
    return [{
      json: {
        ...data,
        context_check: {
          required: false,
          valid: true,
          error: `Unsupported provider for context check: ${data.provider_type}`
        }
      }
    }];
}

return [{
  json: {
    ...data,
    context_check: {
      required: true,
      prompt: checkPrompt,
      provider_type: data.provider_type,
      api_url: apiUrl,
      headers: headers,
      llm_body: llmBody
    }
  }
}];

const data = $input.first().json;
const ctx = data.context_check;

try {
  const response = await fetch(ctx.api_url, {
    method: 'POST',
    headers: ctx.headers,
    body: JSON.stringify(ctx.llm_body)
  });

  if (!response.ok) {
    const errorText = await response.text();
    return [{
      json: {
        error: {
          status: response.status,
          message: errorText
        },
        provider_type: ctx.provider_type
      }
    }];
  }

  const result = await response.json();
  return [{
    json: {
      ...result,
      provider_type: ctx.provider_type
    }
  }];

} catch (e) {
  return [{
    json: {
      error: {
        message: e.message
      },
      provider_type: ctx.provider_type
    }
  }];
}

const prevData = $('Check Context').first().json;
const llmResponse = $input.first().json;
const providerType = llmResponse.provider_type || prevData.context_check?.provider_type;

// Vérifier si erreur LLM
if (!llmResponse || llmResponse.error) {
  // Si erreur LLM, laisser passer (fail open)
  return [{
    json: {
      ...prevData,
      context_check: {
        ...prevData.context_check,
        valid: true,
        error: llmResponse?.error?.message || 'LLM check failed, allowing request'
      }
    }
  }];
}

try {
  // Extraire le texte selon le provider
  let responseText = '';

  switch (providerType) {
    case 'claude':
      responseText = llmResponse.content?.[0]?.text || '';
      break;
    case 'openai':
    case 'mistral':
      responseText = llmResponse.choices?.[0]?.message?.content || '';
      break;
    case 'gemini':
      responseText = llmResponse.candidates?.[0]?.content?.parts?.[0]?.text || '';
      break;
    default:
      responseText = JSON.stringify(llmResponse);
  }

  // Parser le JSON de la réponse
  const jsonMatch = responseText.match(/\{[\s\S]*\}/);

  if (!jsonMatch) {
    // Si pas de JSON valide, considérer comme valide par défaut
    return [{
      json: {
        ...prevData,
        context_check: {
          ...prevData.context_check,
          valid: true,
          raw_response: responseText
        }
      }
    }];
  }

  const parsed = JSON.parse(jsonMatch[0]);

  return [{
    json: {
      ...prevData,
      context_check: {
        ...prevData.context_check,
        valid: parsed.valid === true,
        reason: parsed.reason || null,
        raw_response: responseText
      }
    }
  }];

} catch (e) {
  // En cas d'erreur de parsing, laisser passer (fail open)
  return [{
    json: {
      ...prevData,
      context_check: {
        ...prevData.context_check,
        valid: true,
        error: e.message
      }
    }
  }];
}

const data = $input.first().json;
const ctx = data.allowed_context;

return [{
  json: {
    success: false,
    error: {
      code: 403,
      message: data.context_check.reason || `Cette requête ne correspond pas au contexte autorisé`,
      status: "CONTEXT_VIOLATION",
      details: {
        query: data.query,
        allowed_context: ctx.description,
        suggestion: ctx.suggestion || `Ce bot est dédié à: ${ctx.description}`
      }
    },
    meta: {
      provider: data.provider,
      context_check: {
        passed: false,
        reason: data.context_check.reason
      }
    }
  }
